# Surah Yusuf (chapter 12) — part 11: ayat 101-111 (IDs 1697-1707)
SURAH = 12

ENTRIES = {
1697: (
"اے میرے رب — تو نے مجھے بادشاہت — عطا فرمائی — اور مجھے باتوں کی تعبیر کا علم سکھایا — اے آسمانوں اور زمین کے پیدا کرنے والے — تو ہی دنیا اور آخرت میں میرا کار ساز ہے — مجھے مسلمانی کی حالت میں وفات دے — اور مجھے نیک لوگوں کے ساتھ ملا دے",
"""۱۔ یوسفؑ — کی دعا — اللہ نے بادشاہت اور خوابوں کی تعبیر کا علم دیا؛ دنیا میں فنا کا اعتراف؛ توحید۔
۲۔ ’’رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ وَعَلَّمْتَنِي مِن تَأْوِيلِ الْأَحَادِيثِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيُّيَ فِي الدُّنْيَا وَالْآخِرَۃِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ‘‘ — اے میرے رب — تو نے مجھے بادشاہت — عطا فرمائی — اور مجھے باتوں کی تعبیر کا علم سکھایا — اے آسمانوں اور زمین کے پیدا کرنے والے — تو ہی دنیا اور آخرت میں میرا کار ساز ہے — مجھے مسلمانی کی حالت میں وفات دے — اور مجھے نیک لوگوں کے ساتھ ملا دے — یعنی یوسفؑ نے فرمایا — اے میرے رب — تو نے مجھے بادشاہت عطا فرمائی — اور مجھے باتوں کی تعبیر کا علم سکھایا — اے آسمانوں اور زمین کے پیدا کرنے والے — تو ہی دنیا اور آخرت میں میرا کار ساز ہے — مجھے مسلمانی کی حالت میں وفات دے — اور مجھے صالحین کے ساتھ ملا دے۔
۳۔ عملی سبق: نعمت ملنے پر اللہ کا اعتراف — دنیا و آخرت میں سودا — اللہ کی طرف متوجہ رہنا — بڑوں کی سنت ہے۔"""
),
1698: (
"یہ — غیب کی خبروں — میں سے ہے — ہم — اسے آپ کی طرف وحی کرتے ہیں — اور تم اس وقت ان کے پاس موجود نہ تھے — جب انہوں نے اپنا معاملہ آپس میں طے کیا — اور وہ چالیں چل رہے تھے",
"""۱۔ یہ سارا قصہ قابلِ غور ہے؛ نبی اکرم ﷺ کو علمِ وحی دیا گیا۔
۲۔ ’’ذَٰلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوا أَمْرَهُمْ وَهُمْ يَمْكُرُونَ‘‘ — یہ — غیب کی خبروں — میں سے ہے — ہم — اسے آپ کی طرف وحی کرتے ہیں — اور تم اس وقت ان کے پاس موجود نہ تھے — جب انہوں نے اپنا معاملہ آپس میں طے کیا — اور وہ چالیں چل رہے تھے — یعنی یہ غیب کی خبروں میں سے ہے — ہم اس کو آپ کی طرف وحی کرتے ہیں — اور آپ ان لوگوں کے پاس موجود نہ تھے جب انہوں نے اپنا معاملہ آپس میں طے کیا — اور وہ چالیں چل رہے تھے۔
۳۔ عملی سبق: قرآن مجید کا احوال — سے اپنی نسبت جانچنا — ایمان کی نشانی ہے۔"""
),
1699: (
"اور — آپ کی کوشش کے باوجود — اکثر لوگ ایمان والا نہیں ہوتے",
"""۱۔ اکثر لوگ — نبی کی محنت کے باوجود ایمان نہیں لاتے؛ فیصلہ اللہ کے ہاتھ میں۔
۲۔ ’’وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ‘‘ — اور — آپ کی کوشش کے باوجود — اکثر لوگ ایمان والا نہیں ہوتے — یعنی اگرچہ آپ کی کوشش بہت زیادہ ہو — اکثر لوگ ایمان والے نہیں بنتے۔
۳۔ عملی سبق: نتائج کی فکر چھوڑ کر — ذمہ داری پوری کرنا — ہی مسلمان کا کام ہے۔"""
),
1700: (
"اور — آپ — اس پر — ان سے کوئی اجرت نہیں مانگتے — یہ تو صرف جہانوں والوں — کے لیے ایک نصیحت — ہے",
"""۱۔ تبلیغ میں مزدوری نہیں؛ قرآن عالمی ہدایت ہے۔
۲۔ ’’وَمَا تَسْأَلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ‘‘ — اور — آپ — اس پر — ان سے کوئی اجرت نہیں مانگتے — یہ تو صرف جہانوں والوں — کے لیے ایک نصیحت — ہے — یعنی آپ قرآن کی تبلیغ پر ان سے کوئی اجرت نہیں مانگتے — یہ تو صرف تمام جہانوں کے لیے ایک نصیحت ہے۔
۳۔ عملی سبق: دین کی تبلیغ میں اخلاص ضروری ہے؛ بدلہ اللہ سے لینا ہے۔"""
),
1701: (
"اور — آسمانوں اور زمین میں — کتنی ہی نشانیاں ہیں — جن پر وہ — گزرتے ہیں — اور وہ ان سے اعراض کرتے ہیں",
"""۱۔ کائنات — میں لاکھوں نشانیاں؛ مگر لوگ ان سے نظر چُراتے ہیں۔
۲۔ ’’وَكَأَيِّن مِّن آيَۃٍ فِي السَّمَاوَاتِ وَالْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ‘‘ — اور — آسمانوں اور زمین میں — کتنی ہی نشانیاں ہیں — جن پر وہ — گزرتے ہیں — اور وہ ان سے اعراض کرتے ہیں — یعنی آسمانوں اور زمین میں کتنی ہی نشانیاں ہیں جن پر سے لوگ گزرتے ہیں اور وہ ان سے اعراض کرتے ہیں۔
۳۔ عملی سبق: کائنات کی نشانیاں دیکھ کر فوراً سبق لینا چاہیے؛ غفلت ایمان کو کمزور کرتی ہے۔"""
),
1702: (
"اور — ان میں سے اکثر لوگ اللہ پر ایمان نہیں لاتے — مگر اس حال میں کہ وہ مشرک ہیں",
"""۱۔ ایمان میں شرک کی آمیزش؛ توحید کی تکمیل میں جتن کی ضرورت۔
۲۔ ’’وَمَا يُؤْمِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ‘‘ — اور — ان میں سے اکثر لوگ اللہ پر ایمان نہیں لاتے — مگر اس حال میں کہ وہ مشرک ہیں — یعنی ان میں سے اکثر لوگ اللہ پر ایمان نہیں لاتے مگر اس حال میں کہ وہ مشرک بھی ہیں۔
۳۔ عملی سبق: عقائد کی پاکیزگی — عبادت میں اخلاص — شرک کے ہر پہلو سے بچنا — ضروری ہے۔"""
),
1703: (
"کیا — انھیں اس بات کا یقین ہے کہ ان پر عذاب کا کوئی احاطہ — آئے گا — یا قیامت اچانک آجائے گی اور انھیں خبر بھی نہ ہو",
"""۱۔ بغیر توبہ کے — اللہ کے عذاب یا اچانک قیامت سے کوئی بے فکر نہ ہو۔
۲۔ ’’أَفَأَمِنُوا أَن تَأْتِيَهُمْ غَاشِيَۃٌ مِّنْ عَذَابِ اللَّهِ أَوْ تَأْتِيَهُمُ السَّاعَۃُ بَغْتَۃً وَهُمْ لَا يَشْعُرُونَ‘‘ — کیا — انھیں اس بات کا یقین ہے کہ ان پر عذاب کا کوئی احاطہ — آئے گا — یا قیامت اچانک آجائے گی اور انھیں خبر بھی نہ ہو — یعنی کیا انھیں یقین ہے کہ ان پر عذاب کی کوئی گھیرا ڈالنے والی صورت نازل ہوگی — یا قیامت اچانک آجائے گی اور انھیں خبر بھی نہ ہو۔
۳۔ عملی سبق: ہر وقت موت اور قیامت کی یاد — انسان کو متقی بناتی ہے۔"""
),
1704: (
"کہیے — یہی میرا راستہ ہے — میں اللہ کی طرف بلاتا ہوں پورے — شعور اور یقین کے ساتھ — میں بھی اور میرے پیروکار بھی — اور اللہ پاک ہے — اور میں مشرکوں میں سے نہیں ہوں",
"""۱۔ نبی اکرم ﷺ کے طریقے کا اعلان — توحید کی دعوت — علم اور یقین کے ساتھ۔
۲۔ ’’قُلْ هَٰذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَىٰ بَصِيرَۃٍ أَنَا وَمَنِ اتَّبَعَنِي وَسُبْحَانَ اللَّهِ وَمَا أَنَا مِنَ الْمُشْرِكِينَ‘‘ — کہیے — یہی میرا راستہ ہے — میں اللہ کی طرف بلاتا ہوں پورے — شعور اور یقین کے ساتھ — میں بھی اور میرے پیروکار بھی — اور اللہ پاک ہے — اور میں مشرکوں میں سے نہیں ہوں — یعنی کہیے یہی میرا راستہ ہے — میں اللہ کی طرف بلاتا ہوں پورے شعور اور یقین کے ساتھ — میں بھی اور میرے تابعدار بھی — اور اللہ پاک ہے — اور میں مشرکوں میں سے نہیں ہوں۔
۳۔ عملی سبق: تحریک اسلامیہ کی بنیاد علم اور بصیرت پر ہونی چاہیے؛ جذبات نہیں۔"""
),
1705: (
"اور ہم نے آپ سے پہلے — بستیوں کے رہنے والوں میں سے — ہی مرد بھیجے جن کی طرف وحی کرتے تھے — کیا پھر انھوں نے زمین میں چل پھر کر یہ نہیں دیکھا کہ ان سے پہلوں کا کیا انجام ہوا — اور آخرت کا گھر ان لوگوں کے لیے بہتر ہے جو تقوی او اختیار کرتے ہیں — کیا تم پھر بھی عقل نہیں پکڑتے",
"""۱۔ ہر نبی مرد اور بستی سے؛ ماضی کی قوموں کے انجام سے سبق؛ آخرت بہتر۔
۲۔ ’’وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم مِّنْ أَهْلِ الْقُرَىٰ أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَۃُ الَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ الْآخِرَۃِ خَيْرٌ لِّلَّذِينَ اتَّقَوا أَفَلَا تَعْقِلُونَ‘‘ — اور ہم نے آپ سے پہلے — بستیوں کے رہنے والوں میں سے — ہی مرد بھیجے جن کی طرف وحی کرتے تھے — کیا پھر انھوں نے زمین میں چل پھر کر یہ نہیں دیکھا کہ ان سے پہلوں کا کیا انجام ہوا — اور آخرت کا گھر ان لوگوں کے لیے بہتر ہے جو تقوی او اختیار کرتے ہیں — کیا تم پھر بھی عقل نہیں پکڑتے — یعنی ہم نے آپ سے پہلے صرف مردوں کو رسول بنایا — جن کی طرف وحی کرتے تھے اور وہ بستیوں کے رہنے والے تھے — کیا پھر ان لوگوں نے زمین میں چل پھر کر نہیں دیکھا کہ ان سے پہلوں کا کیا انجام ہوا — اور آخرت کا گھر ان لوگوں کے لیے بہتر ہے جو تقوی اختیار کرتے ہیں — کیا تم پھر بھی عقل نہیں پکڑتے۔
۳۔ عملی سبق: تاریخ سے سبق نہ لینا — عقل کی محرومی کا ثبوت ہے؛ تقویٰ اختیار کیجیے۔"""
),
1706: (
"یہاں تک کہ جب رسول مایوس ہو گئے اور انھوں نے گمان کیا کہ ان سے جھوٹ بولا گیا تو ان کے پاس ہماری مدد آ پہنچی — پھر ہم نے جس کو چاہا بچالیا — اور ہمارا عذاب مجرموں سے ٹالا نہیں جا سکتا",
"""۱۔ نصرت ہمیشہ امید کی حد پر آتی ہے؛ اللہ کے وعدوں پر یقین رکھیے۔
۲۔ ’’حَتَّىٰ إِذَا اسْتَيْأَسَ الرُّسُلُ وَظَنُّوا أَنَّهُمْ قَدْ كُذِبُوا جَاءَهُمْ نَصْرُنَا فَنُجِّيَ مَن نَّشَاءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ الْقَوْمِ الْمُجْرِمِينَ‘‘ — یہاں تک کہ جب رسول مایوس ہو گئے اور انھوں نے گمان کیا کہ ان سے جھوٹ بولا گیا تو ان کے پاس ہماری مدد آ پہنچی — پھر ہم نے جس کو چاہا بچالیا — اور ہمارا عذاب مجرموں سے ٹالا نہیں جا سکتا — یعنی یہاں تک کہ جب رسول مایوس ہو گئے اور انھوں نے گمان کیا کہ ان سے جھوٹ بولا گیا — تو ان کے پاس ہماری مدد آ پہنچی — پھر ہم نے جس کو چاہا بچالیا — اور ہمارا عذاب مجرموں سے ٹالا نہیں جا سکتا۔
۳۔ عملی سبق: مایوس کن حالات میں اللہ کی نصرت پر کامل بھروسہ رکھنا — اہلِ ایمان کا شعار ہے۔"""
),
1707: (
"یقیناً ان کے قصوں میں صاحبان عقل کے لیے بڑی عبرت ہے — یہ کوئی گھڑا ہوا قصہ نہیں ہے بلکہ اس کی تصدیق ہے جو اس سے پہلے ہے اور ہر چیز کی تفصیل ہے اور ایمان والوں کے لیے ہدایت اور رحمت ہے",
"""۱۔ سورہ یوسفؑ کا خلاصہ؛ قرآن کی حقانیت اور اس کی جامعیت پر اللہ کی قسم؛ ایمان والوں کے لیے ہدایت و رحمت۔
۲۔ ’’لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَۃٌ لِّأُولِي الْأَلْبَابِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَيْءٍ وَهُدًى وَرَحْمَۃً لِّقَوْمٍ يُؤْمِنُونَ‘‘ — یقیناً ان کے قصوں میں صاحبان عقل کے لیے بڑی عبرت ہے — یہ کوئی گھڑا ہوا قصہ نہیں ہے بلکہ اس کی تصدیق ہے جو اس سے پہلے ہے اور ہر چیز کی تفصیل ہے اور ایمان والوں کے لیے ہدایت اور رحمت ہے — یعنی یقیناً ان کے قصوں میں صاحبانِ عقل کے لیے بڑی عبرت ہے — یہ کوئی گھڑا ہوا قصہ نہیں ہے — بلکہ اس کی تصدیق ہے جو اس سے پہلے گزرا — اور ہر چیز کی تفصیل ہے — اور ایمان والوں کے لیے ہدایت اور رحمت ہے۔
۳۔ عملی سبق: قرآن کو روزانہ پڑھنا، سمجھنا اور عمل کرنا — زندگی کی سب سے بڑی کامیابی ہے۔"""
),
}
